// Synthetic replica of nativewind@4 sources (TS). Exposes the styling runtime.
// The real library depends on a Babel preset (jsxImportSource: "nativewind")
// that rewrites className props and on a Tailwind-compiled CSS entry; a plain
// bundler build resolves and bundles this runtime but applies neither.
export const NATIVEWIND_OK = "NATIVEWIND_OK";

const styleRegistry = new Map<string, Record<string, unknown>>();

export function cssInterop<T>(component: T, _mapping: Record<string, unknown>): T {
  return component;
}

export function remapProps<T>(component: T, _mapping: Record<string, unknown>): T {
  return component;
}

export function styled<T>(component: T): T {
  return component;
}

export function verifyInstallation(): void {
  // In the real package this throws unless the Babel preset injected a marker.
  if (!styleRegistry) {
    throw new Error("NativeWind: the Babel preset is not configured.");
  }
}
